import classNames from "classnames";
import { useCallback, useEffect, useState, useMemo } from 'react'

import { AnswerButton } from "./components/AnswerButton";
import { QuestionImage } from "./components/QuestionImage";
import { QuestionSelector } from "./components/QuestionSelector";
import { usePageAndQuestion } from "./hooks/usePageAndQuestion";
import { useQuestionData } from "./hooks/useQuestionData";
import { useRandomizedQuestionOrder } from "./hooks/useRandomizedQuestionOrder";

import './App.css'

function App() {
  const [isRandomOrder, setIsRandomOrder] = useState(true);
  const [chosenAnswer, setChosenAnswer] = useState<number | null>(null);
  const [questionIndex, setQuestionIndex] = useState<number | null>(null); // Index in questionArray
  const [answeredQuestions, setAnsweredQuestions] = useState(0);
  const [correctQuestions, setCorrectQuestions] = useState(0);

  const { questions: questionArray, pages, chapters } = useQuestionData();
  const { order: randomizedQuestionOrder, queueIndex, setQueueIndex } = useRandomizedQuestionOrder(questionArray);
  const { page, question } = usePageAndQuestion(questionArray, questionIndex);

  useEffect(() => {
    if (!questionArray || randomizedQuestionOrder.length === 0 || queueIndex === null) {
      return;
    }

    setQuestionIndex(isRandomOrder ? randomizedQuestionOrder[queueIndex] : 0);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [randomizedQuestionOrder, questionArray]);
  // Ignore isRandomOrder, as it causes for setting of first page after initial page change

  useEffect(() => {
    setChosenAnswer(null);
  }, [questionIndex]);

  const nextQuestion = useCallback(() => {
    if (!questionArray || questionIndex === null) {
      return;
    }

    if (isRandomOrder && queueIndex !== null) {
      const nextQuestionQueueIndex = queueIndex < questionArray.length - 1 ? queueIndex + 1 : 0;
      setQuestionIndex(randomizedQuestionOrder[nextQuestionQueueIndex]);
      setQueueIndex(nextQuestionQueueIndex);
      return;
    }

    const nextQuestionIndex = questionIndex + 1;
    setQuestionIndex(nextQuestionIndex === questionArray.length ? 0 : nextQuestionIndex);
  }, [questionArray, questionIndex, queueIndex, isRandomOrder, randomizedQuestionOrder, setQueueIndex]);

  const prevQuestion = useCallback(() => {
    if (!questionArray || questionIndex === null) {
      return;
    }

    if (isRandomOrder && queueIndex !== null) {
      const previousQuestionQueueIndex = queueIndex > 0 ? queueIndex - 1 : questionArray.length - 1;
      setQuestionIndex(randomizedQuestionOrder[previousQuestionQueueIndex]);
      setQueueIndex(previousQuestionQueueIndex);
      return;
    }

    const previousQuestionIndex = questionIndex - 1;
    setQuestionIndex(previousQuestionIndex < 0 ? questionArray.length - 1 : previousQuestionIndex);
  }, [questionArray, questionIndex, queueIndex, randomizedQuestionOrder, isRandomOrder, setQueueIndex]);

  const countAnswers = useCallback((isCorrect: boolean) => {
    setAnsweredQuestions(counter => counter + 1);
    
    if (isCorrect) {
      setCorrectQuestions(counter => counter + 1);
    }
  }, []);

  const rightAnswer = useMemo(() => {
    if (!questionArray || !questionIndex) {
      return;
    }

    return questionArray[questionIndex].answer;
  }, [questionArray, questionIndex]);

  const chooseAnswer = useCallback((number: number) => {
    // Count answers only when chosenAnswer is still null, if not, it means it got corrected
    if (!chosenAnswer) {
      countAnswers(number === rightAnswer);
    }

    setChosenAnswer(number);
    if (number === rightAnswer) {
      setTimeout(() => {
        nextQuestion();
      }, 200);
    }
  }, [rightAnswer, nextQuestion, chosenAnswer, countAnswers]);

  if (!questionArray) {
    return null;
  }

  return (
    <div className="question-container">
      <div className={classNames("question-counter", {"passed": (correctQuestions / answeredQuestions) > 0.93})}>
        {correctQuestions} / {answeredQuestions}
      </div>
      <QuestionSelector
        isRandomOrder={isRandomOrder}
        setIsRandomOrder={setIsRandomOrder}
        pages={pages}
        chapters={chapters}
        questionIndex={questionIndex || 0}
        setQuestionIndex={setQuestionIndex}
      />
      <div className="info">
        <h2>{page}. lapa, {question}. jautājums</h2>
      </div>
      <QuestionImage
        page={page}
        question={question}
        pages={pages}
      />
      <div className="answers">
        {[1, 2, 3, 4].map(answer => (
          <AnswerButton
            key={answer}
            answerNumber={answer}
            correctAnswer={rightAnswer ?? 0}
            chosenAnswer={chosenAnswer}
            chooseAnswer={chooseAnswer}
          />
        ))}
      </div>
      <div className="navigation">
        <button onClick={prevQuestion}>
          &#x2190;
        </button>
        <button onClick={nextQuestion}>
          &#x2192;
        </button>
      </div>
    </div>
  )
}

export default App
