import { useCallback, useEffect, useRef, useState } from "react";
import { Page } from "../types";

interface UseImageProps {
    page: number | null;
    question: number | null;
    pages: Page[];
}

interface UseImageReturn {
    isLoading: boolean;
    hideLeft: boolean;
    hideRight: boolean;
}

export function useImage({ page, question, pages }: UseImageProps): UseImageReturn {
    const [leftImage, setLeftImage] = useState<HTMLImageElement>();
    const [rightImage, setRightImage] = useState<HTMLImageElement>();
    const [hideLeft, setHideLeft] = useState(false);
    const [hideRight, setHideRight] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const resizeThrottleId = useRef<NodeJS.Timeout>(null);

    useEffect(() => {
        if (!page) {
            return;
        }

        (async () => {
            const imageContainer = document.getElementById("left-image");
            const questionTextContainer = document.getElementById("right-image");

            if (!imageContainer || !questionTextContainer) {
                return;
            }
        
            try {
                setIsLoading(true);
                const importedImage = await import(`../../../questions/${page}.JPEG`);

                const leftImg = new Image();
                leftImg.src = importedImage.default;
                leftImg.className = "image";
            
                const rightImg = new Image();
                rightImg.src = importedImage.default;
                rightImg.className = "image";
            
                // Split image into two for smaller screens, so the image and text are displayed seperately
                leftImg.onload = () => {
                if (imageContainer.children.length > 0) {
                    imageContainer.replaceChildren(leftImg);
                } else {
                    imageContainer.appendChild(leftImg);
                }
            
                if (questionTextContainer.children.length > 0) {
                    questionTextContainer.replaceChildren(rightImg);
                } else {
                    questionTextContainer.appendChild(rightImg);
                }
            
                setLeftImage(leftImg);
                setRightImage(rightImg);
                setIsLoading(false);
                }
            } catch {
                throw new Error("Can't find page " + page);        
            } finally {
                setIsLoading(false);
            }
        })();
    }, [page])

    const adjustTopOffset = useCallback(() => {
        const pageData = pages.find(el => el.page === page);

        if(!leftImage || !rightImage || !question || !pageData) {
            return;
        }

        leftImage.style.top = `${(-leftImage.height / 5) * (pageData.layout.get(question)! - 1)}px`;
        rightImage.style.top = `${(-rightImage.height / 5) * (pageData.layout.get(question)! - 1)}px`;
        setHideLeft(pageData.layout.get(question) === pageData.layout.get(question - 1));
        setHideRight(pageData.layout.get(question) === pageData.layout.get(question + 1));
    }, [leftImage, rightImage, question, pages, page]);

      const resizeListener = useCallback(() => {
        if (!resizeThrottleId.current) {
          adjustTopOffset();
    
          // Do the throttle
          resizeThrottleId.current = setTimeout(() => {
            resizeThrottleId.current = null;
            adjustTopOffset();
          }, 100);
        }
      }, [adjustTopOffset]);
    
      useEffect(() => {  
        // Do first call before resize
        resizeListener();
    
        window.addEventListener("resize", resizeListener);
    
        return () => {
          window.removeEventListener("resize", resizeListener)
        }
      }, [resizeListener]);

    useEffect(() => {
        adjustTopOffset();
    }, [adjustTopOffset, page, question]);

    return {
        isLoading: isLoading,
        hideLeft: hideLeft,
        hideRight: hideRight,
    };
}
