import { useCallback, useEffect, useState } from "react";
import { Question } from "../types";
import { shuffle } from "../utils/utils";

interface RandomizedQuestionOrder {
    order: number[];
    queueIndex: number | null;
    setQueueIndex: (index: number) => void;
}

const QUEUE_INDEX_KEY = "csn.queueIndex";
const RANDOM_ORDER_KEY = "csn.ranomizedQueue";

export function useRandomizedQuestionOrder(questionArray: Question[] | null): RandomizedQuestionOrder {
    const [order, setOrder] = useState<number[]>([]);
    const [queueIndex, setQueueIndex] = useState<number | null>(null);

    useEffect(() => {
        if (questionArray === null) {
            return;
        }

        // Read from localStorage if there is order, so order remains same between refreshes & you can continue where left off
        const existingIndex = localStorage.getItem(QUEUE_INDEX_KEY);
        setQueueIndex(existingIndex ? Number(existingIndex) : 0); // Set initial queueIndex

        const existingRandomOrder = localStorage.getItem(RANDOM_ORDER_KEY);
        if (existingRandomOrder !== null) {
            setOrder(existingRandomOrder.split(",").map(Number));
            return;
        }

        const questionIndexArray = questionArray.map((_el, idx) => idx);
        shuffle(questionIndexArray);
        localStorage.setItem(RANDOM_ORDER_KEY, questionIndexArray.join(","));
        setOrder(questionIndexArray);
    }, [questionArray]);

    // Enhance setQueueIndex with localStorage logic
    const setQueueIndexEnhanced = useCallback((index: number) => {
        localStorage.setItem(QUEUE_INDEX_KEY, index.toString());
        setQueueIndex(index);
    }, []);

    return {
        order: order,
        queueIndex: order.length > 0 ? queueIndex : null, // In case if order is [], it can cause out of bounds read
        setQueueIndex: setQueueIndexEnhanced,
    }
}
