import { useMemo } from "react";
import { Question } from "../types";

interface PageAndQuestion {
    page: number | null;
    question: number | null;
}

export function usePageAndQuestion(questionArray: Question[] | null, questionIndex: number | null): PageAndQuestion {
    const page = useMemo(() => {
        if (!questionArray || questionIndex === null) {
        return null;
        }

        return questionArray[questionIndex].page;
    }, [questionArray, questionIndex]);

    const question = useMemo(() => {
        if (!questionArray || questionIndex === null) {
        return null;
        }

        return questionArray[questionIndex].question;
    }, [questionArray, questionIndex]);

    return { page: page, question: question };
}
