/**
 * Makes map of question layout in page.
 * Processing the splitRows of page, row of each question is calculated.
 */
export function getQuestionLayout(splitRows: number[] = []): Map<number, number> {
    const layoutMap: Map<number, number> = new Map();
    const totalQuestions = 5 + splitRows.length;
    let iterator = 0;
    let row = 1;

    for (let i = 0; i < totalQuestions; i++) {
        if (splitRows.indexOf(iterator) > -1) {
            layoutMap.set(i + 1, row);
            i++;
        }

        layoutMap.set(i + 1, row);
        iterator++;
        row++;
    }

    return layoutMap;
}

/**
 * Shuffles given array containing numbers
 */
export function shuffle(array: number[]): void {
    let currentIndex = array.length;

    // While there remain elements to shuffle...
    while (currentIndex !== 0) {
  
        // Pick a remaining element...
        let randomIndex = Math.floor(Math.random() * currentIndex);
        currentIndex--;

        // And swap it with the current element.
        [array[currentIndex], array[randomIndex]] = [array[randomIndex], array[currentIndex]];
    }
}
