import classNames from "classnames";
import { ChangeEvent, useCallback, useMemo, useState } from "react";

import { MenuIcon } from "./MenuIcon";
import { Toggle } from "./Toggle";
import { Chapter, Page } from "../types";

import '../App.css'

interface QuestionSelectorProps {
    isRandomOrder: boolean;
    setIsRandomOrder: (isRandom: boolean) => void;
    pages: Page[];
    chapters: Chapter[];
    questionIndex: number;
    setQuestionIndex: (index: number) => void;
}

export function QuestionSelector({
    isRandomOrder,
    setIsRandomOrder,
    pages,
    chapters,
    questionIndex,
    setQuestionIndex,
}: QuestionSelectorProps) {
    const [showDialog, setShowDialog] = useState(false);

    const toggleDialog = useCallback(() => {
        setShowDialog(show => !show);
    }, []);

    const changeRandomness = useCallback(() => {
        setIsRandomOrder(!isRandomOrder);
    }, [isRandomOrder, setIsRandomOrder]);    

    const changePage = useCallback((event: ChangeEvent<HTMLSelectElement>) => {
        setQuestionIndex(Number(event.currentTarget.value));
        setIsRandomOrder(false);
    }, [setIsRandomOrder, setQuestionIndex]);

    const activeChapterQuestionIndex = useMemo(() => {
        const previousChapters = chapters.filter(el => el.questionIndex <= questionIndex);

        return previousChapters[previousChapters.length - 1].questionIndex;
    }, [questionIndex, chapters]);

    const activePageQuestionIndex = useMemo(() => {
        const previousPages = pages.filter(el => el.questionIndex <= questionIndex);

        return previousPages[previousPages.length - 1].questionIndex;
    }, [questionIndex, pages]);

    return (
        <>
            <button className="sidebar-toggle" onClick={toggleDialog}>
                <MenuIcon />
            </button>
            <div className={classNames("dialog", { "show": showDialog })} >
                <div className="dialog-content">
                    <div className="question-selector">
                    <div className="select-group">
                        <label htmlFor="isRandom">Random:</label>
                        <Toggle checked={isRandomOrder} onChange={changeRandomness} />
                    </div>
                    <div className="select-group">
                        <label htmlFor="chapter">Nodaļa:</label>
                        <select name="chapter" id="chapter" onChange={changePage} value={activeChapterQuestionIndex}>
                            {chapters.map(chapter => (
                                <option key={chapter.questionIndex} value={chapter.questionIndex}>
                                    {chapter.name}
                                </option>
                            ))}
                        </select>
                    </div>
                    <div className="select-group">
                        <label htmlFor="page">Lapa:</label>
                        <select name="page" id="page" onChange={changePage} value={activePageQuestionIndex}>
                            {pages.map(page => (
                                <option key={page.questionIndex} value={page.questionIndex}>
                                    {page.page}
                                </option>
                            ))}
                        </select>
                    </div>
                    </div>
                    <button onClick={toggleDialog}>OK</button>
                </div>
            </div>
        </>
    )
}
