import classNames from "classnames";

interface AnswerButtonProps {
  answerNumber: number;
  correctAnswer: number;
  chosenAnswer: number | null;
  chooseAnswer: (answerNumber: number) => void;
}

export function AnswerButton({ answerNumber, correctAnswer, chosenAnswer, chooseAnswer }: AnswerButtonProps) {
    return (
        <button
          className={classNames(
            {
              "correct": correctAnswer === answerNumber && chosenAnswer !== null,
              "wrong": correctAnswer !== answerNumber && chosenAnswer === answerNumber,
            })}
          onClick={() => chooseAnswer(answerNumber)}
        >
          {answerNumber}
        </button>
    )
}
